css:
:where(.wtyg-map-stand_your_ground){--card:rgba(15,20,28,.94);--line:#2a3442;--ink:#e6e4e0;--mute:#a3a9b0}
:where(.wtyg-map-stand_your_ground),:where(.wtyg-map-stand_your_ground){margin:0;height:100%;background:#0d1117;color:var(--ink);font:14px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0;background:#0d1117}
:where(.wtyg-map-stand_your_ground) .card{position:absolute;z-index:800;background:var(--card);border:1px solid var(--line);border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.45)}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="key"],#wtyg-noid-key){top:12px;left:12px;width:320px;max-height:calc(100% - 24px);overflow:auto;padding:12px 14px}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="key"],#wtyg-noid-key) h1{font-size:18px;margin:0 0 2px}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="key"],#wtyg-noid-key) .lede{color:var(--mute);margin:0 0 8px;font-size:12.5px}
:where(.wtyg-map-stand_your_ground) .row{display:flex;gap:8px;align-items:flex-start;padding:5px 0;border-top:1px solid var(--line)}
:where(.wtyg-map-stand_your_ground) .row input{margin-top:3px;accent-color:#5d80c2}
:where(.wtyg-map-stand_your_ground) .row label{flex:1;cursor:pointer;font-size:13px}
:where(.wtyg-map-stand_your_ground) .row .n{color:var(--mute);font-size:11.5px}
:where(.wtyg-map-stand_your_ground) .sw{display:inline-block;width:12px;height:12px;border-radius:2px;margin-right:6px;vertical-align:-1px}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="infoBtn"],#wtyg-noid-infoBtn){top:12px;right:12px;padding:7px 12px;cursor:pointer;font-weight:600}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info){top:56px;right:12px;width:400px;max-height:calc(100% - 70px);overflow:auto;padding:14px 16px;display:none}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info).open{display:block}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info) h2{font-size:15px;margin:14px 0 6px}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info) h2:first-child{margin-top:0}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info) p,:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info) li{font-size:12.8px}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info) ul{padding-left:18px;margin:4px 0}
:where(.wtyg-map-stand_your_ground) .mute{color:var(--mute)}
:where(.wtyg-map-stand_your_ground) a{color:#9fc2e6}
:where(.wtyg-map-stand_your_ground) .leaflet-popup-content-wrapper{background:#131a24;color:var(--ink);border:1px solid var(--line);border-radius:9px}
:where(.wtyg-map-stand_your_ground) .leaflet-popup-tip{background:#131a24}
:where(.wtyg-map-stand_your_ground) .leaflet-popup-content{margin:12px 14px;max-height:60vh;overflow:auto;min-width:240px}
:where(.wtyg-map-stand_your_ground) .leaflet-container a.leaflet-popup-close-button{color:#ccc}
:where(.wtyg-map-stand_your_ground) .hp h3{margin:2px 0 4px;font-size:15px}
:where(.wtyg-map-stand_your_ground) .hp-k{font-size:10.5px;letter-spacing:.6px;text-transform:uppercase;color:#8fbfcd}
:where(.wtyg-map-stand_your_ground) .hp-lead{margin:4px 0 8px}
:where(.wtyg-map-stand_your_ground) .hp p{margin:4px 0}
:where(.wtyg-map-stand_your_ground) .hp-src{color:#a3a9b0;font-size:11.2px;margin-top:8px;border-top:1px solid #2a3442;padding-top:6px}
:where(.wtyg-map-stand_your_ground) .leaflet-control-attribution{background:rgba(13,17,23,.75)!important;color:#8d9399!important}
:where(.wtyg-map-stand_your_ground) .leaflet-control-attribution a{color:#a7b9d0!important}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="toggleKey"],#wtyg-noid-toggleKey){display:none}
@media (max-width:720px){:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="key"],#wtyg-noid-key){width:auto;right:12px;max-height:45%}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="key"],#wtyg-noid-key).min .body{display:none}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="toggleKey"],#wtyg-noid-toggleKey){display:inline-block;float:right;background:none;border:1px solid var(--line);color:var(--ink);border-radius:6px;padding:1px 8px}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="infoBtn"],#wtyg-noid-infoBtn){top:auto;bottom:24px;left:12px;right:auto}
:where(.wtyg-map-stand_your_ground) :is([data-wtyg-id="info"],#wtyg-noid-info){top:auto;bottom:66px;left:12px;right:12px;width:auto;max-height:60%}}
